"""Factory for search engines."""

from __future__ import annotations

from xla_ciq.search.base import SearchEngine
from xla_ciq.search.compileiq_runtime import CompileIqRuntimeEngine
from xla_ciq.search.mock import MockSearchEngine


def get_search_engine(*, mock: bool) -> SearchEngine:
    if mock:
        return MockSearchEngine()
    return CompileIqRuntimeEngine()

"""HLO shape helpers for buffer sizing and launch config."""

from __future__ import annotations

import re
from dataclasses import dataclass

_SHAPE_RE = re.compile(
    r"^([a-z][a-z0-9]*)\[(\d+(?:,\d+)*)\]$",
    re.IGNORECASE,
)

_DTYPE_BYTES = {
    "pred": 1,
    "s8": 1,
    "u8": 1,
    "s16": 2,
    "u16": 2,
    "f16": 2,
    "bf16": 2,
    "s32": 4,
    "u32": 4,
    "f32": 4,
    "s64": 8,
    "u64": 8,
    "f64": 8,
    "c64": 8,
    "c128": 16,
}

SUPPORTED_DTYPES = frozenset(_DTYPE_BYTES)


def is_supported_dtype(dtype: str) -> bool:
    """True when dtype is an HLO element type we can size buffers for."""
    return dtype.lower() in _DTYPE_BYTES


@dataclass(frozen=True)
class ParsedShape:
    dtype: str
    dims: tuple[int, ...]

    @property
    def numel(self) -> int:
        n = 1
        for d in self.dims:
            n *= d
        return n

    @property
    def element_size(self) -> int:
        if self.dtype not in _DTYPE_BYTES:
            raise ValueError(f"unsupported dtype for launch sizing: {self.dtype}")
        return _DTYPE_BYTES[self.dtype]

    @property
    def nbytes(self) -> int:
        return self.numel * self.element_size


def parse_shape_token(token: str) -> ParsedShape:
    match = _SHAPE_RE.match(token.strip())
    if not match:
        raise ValueError(f"invalid shape token: {token!r}")
    dtype = match.group(1).lower()
    dims = tuple(int(x) for x in match.group(2).split(","))
    return ParsedShape(dtype=dtype, dims=dims)


def grid_for_numel(numel: int, block_size: int) -> int:
    if block_size <= 0:
        raise ValueError("block_size must be positive")
    return max(1, (numel + block_size - 1) // block_size)

"""Minimal CUDA driver helpers for loading cubin and timing a kernel."""

from __future__ import annotations

import ctypes
import statistics
from dataclasses import dataclass

try:
    from cuda.bindings import driver as cuda
except ImportError:  # Keep mock and inspection commands usable without CUDA.
    cuda = None

from xla_ciq.xla.tensor_map import TensorMapError, TensorMapSpec

# CUtensorMap is an opaque 128-byte struct that must be 64-byte aligned both
# when the driver fills it in and when it is handed to a kernel by value.
TENSOR_MAP_NBYTES = 128
_TENSOR_MAP_ALIGN = 64

_TENSOR_MAP_DTYPES = {
    "u8": "UINT8",
    "s8": "UINT8",
    "pred": "UINT8",
    "u16": "UINT16",
    "s16": "UINT16",
    "f16": "FLOAT16",
    "bf16": "BFLOAT16",
    "u32": "UINT32",
    "s32": "INT32",
    "f32": "FLOAT32",
    "u64": "UINT64",
    "s64": "INT64",
    "f64": "FLOAT64",
}

_SWIZZLE_NAMES = {0: "NONE", 32: "32B", 64: "64B", 128: "128B"}

# A kernel gets 48 KiB of dynamic shared memory unless it opts in, and Hopper
# tile kernels routinely ask for more, so the opt-in is part of launching them.
_DEFAULT_MAX_DYNAMIC_SHARED = 48 * 1024


class CudaError(RuntimeError):
    """CUDA driver API failure."""


def _require_cuda_bindings() -> None:
    if cuda is None:
        raise CudaError(
            "CUDA Python driver bindings are unavailable; install a compatible "
            "cuda-python package for real GPU execution"
        )


def _check(result):
    if isinstance(result, tuple):
        err, *rest = result
    else:
        err, rest = result, []
    if err != cuda.CUresult.CUDA_SUCCESS:
        raise CudaError(str(err))
    if not rest:
        return None
    if len(rest) == 1:
        return rest[0]
    return tuple(rest)


def _as_dim3(value: int | tuple[int, int, int]) -> tuple[int, int, int]:
    if isinstance(value, tuple):
        if len(value) != 3:
            raise ValueError(f"expected 3-tuple grid/block, got {value!r}")
        return int(value[0]), int(value[1]), int(value[2])
    return int(value), 1, 1


@dataclass
class TimedLaunchResult:
    median_ms: float
    samples_ms: list[float]


def _aligned_buffer(payload: bytes, align: int) -> tuple[ctypes.Array, int]:
    """Host buffer holding payload at an `align`-byte boundary."""
    backing = (ctypes.c_char * (len(payload) + align))()
    base = ctypes.addressof(backing)
    offset = (-base) % align
    ctypes.memmove(base + offset, payload, len(payload))
    return backing, base + offset


def encode_tensor_map(
    spec: TensorMapSpec, *, device_ptr: int, swizzle_bytes: int
) -> bytes:
    """Build the 128-byte CUtensorMap describing `device_ptr` with this layout."""
    _require_cuda_bindings()
    spec.validate()
    dtype_name = _TENSOR_MAP_DTYPES.get(spec.dtype)
    if dtype_name is None:
        raise TensorMapError(f"no CUtensorMap data type for dtype {spec.dtype!r}")
    swizzle_name = _SWIZZLE_NAMES.get(swizzle_bytes)
    if swizzle_name is None:
        raise TensorMapError(f"invalid swizzle: {swizzle_bytes}")

    encoded = _check(
        cuda.cuTensorMapEncodeTiled(
            getattr(cuda.CUtensorMapDataType, f"CU_TENSOR_MAP_DATA_TYPE_{dtype_name}"),
            spec.rank,
            device_ptr,
            [cuda.cuuint64_t(x) for x in spec.dims],
            [cuda.cuuint64_t(x) for x in spec.strides],
            [cuda.cuuint32_t(x) for x in spec.box],
            [cuda.cuuint32_t(x) for x in spec.effective_element_strides],
            cuda.CUtensorMapInterleave.CU_TENSOR_MAP_INTERLEAVE_NONE,
            getattr(cuda.CUtensorMapSwizzle, f"CU_TENSOR_MAP_SWIZZLE_{swizzle_name}"),
            cuda.CUtensorMapL2promotion.CU_TENSOR_MAP_L2_PROMOTION_L2_128B,
            cuda.CUtensorMapFloatOOBfill.CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE,
        )
    )
    return bytes((ctypes.c_char * TENSOR_MAP_NBYTES).from_address(int(encoded.getPtr())))


class CudaContext:
    def __init__(self) -> None:
        _require_cuda_bindings()
        _check(cuda.cuInit(0))
        self.device = _check(cuda.cuDeviceGet(0))
        self._ctx = _check(cuda.cuDevicePrimaryCtxRetain(self.device))
        _check(cuda.cuCtxSetCurrent(self._ctx))

    def close(self) -> None:
        _check(cuda.cuDevicePrimaryCtxRelease(self.device))

    def __enter__(self) -> CudaContext:
        return self

    def __exit__(self, *args) -> None:
        self.close()

    def load_cubin(self, cubin_path: str):
        # cuda-python driver bindings expect bytes paths.
        return _check(cuda.cuModuleLoad(cubin_path.encode("utf-8")))

    def get_function(self, module, name: str):
        return _check(cuda.cuModuleGetFunction(module, name.encode("utf-8")))

    def alloc(self, nbytes: int):
        return _check(cuda.cuMemAlloc(nbytes))

    def free(self, ptr) -> None:
        _check(cuda.cuMemFree(ptr))

    def memset(self, ptr, value: int, nbytes: int) -> None:
        _check(cuda.cuMemsetD8(ptr, value, nbytes))

    def unload(self, module) -> None:
        _check(cuda.cuModuleUnload(module))

    def allow_dynamic_shared_memory(self, func, nbytes: int) -> None:
        """Raise this kernel's dynamic shared memory cap above the 48 KiB default."""
        if nbytes <= _DEFAULT_MAX_DYNAMIC_SHARED:
            return
        _check(
            cuda.cuFuncSetAttribute(
                func,
                cuda.CUfunction_attribute.CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
                int(nbytes),
            )
        )

    def time_launch(
        self,
        func,
        *,
        grid: int | tuple[int, int, int],
        block: int | tuple[int, int, int],
        arg_values: list,
        trials: int,
        warmup: int = 2,
        shared_memory_bytes: int = 0,
    ) -> TimedLaunchResult:
        gx, gy, gz = _as_dim3(grid)
        bx, by, bz = _as_dim3(block)
        start = _check(cuda.cuEventCreate(0))
        end = _check(cuda.cuEventCreate(0))
        samples: list[float] = []
        packed, _holders = _pack_kernel_args(arg_values)
        try:
            for i in range(warmup + trials):
                _check(cuda.cuEventRecord(start, 0))
                _check(
                    cuda.cuLaunchKernel(
                        func,
                        gx,
                        gy,
                        gz,
                        bx,
                        by,
                        bz,
                        int(shared_memory_bytes),
                        0,
                        packed,
                        0,
                    )
                )
                _check(cuda.cuEventRecord(end, 0))
                _check(cuda.cuEventSynchronize(end))
                ms = _check(cuda.cuEventElapsedTime(start, end))
                if i >= warmup:
                    samples.append(float(ms))
        finally:
            _check(cuda.cuEventDestroy(start))
            _check(cuda.cuEventDestroy(end))
        return TimedLaunchResult(
            median_ms=float(statistics.median(samples)),
            samples_ms=samples,
        )


def _pack_kernel_args(arg_values: list) -> tuple[ctypes.Array, list]:
    """Build the void** kernel parameter array.

    Each slot holds the address of the argument's value: a device pointer for
    buffer arguments, or the descriptor bytes themselves for by-value
    arguments such as a CUtensorMap.
    """
    holders: list = []
    slots: list[ctypes.c_void_p] = []
    for value in arg_values:
        if isinstance(value, (bytes, bytearray)):
            backing, address = _aligned_buffer(bytes(value), _TENSOR_MAP_ALIGN)
            holders.append(backing)
            slots.append(ctypes.c_void_p(address))
        else:
            holder = ctypes.c_uint64(int(value))
            holders.append(holder)
            slots.append(ctypes.cast(ctypes.addressof(holder), ctypes.c_void_p))
    packed = (ctypes.c_void_p * len(slots))(*slots)
    return packed, holders

"""Lightweight PTX entry metadata for CUDA launch configuration."""

from __future__ import annotations

import re
from dataclasses import dataclass

_ENTRY_RE = re.compile(
    r"\.visible\s+\.entry\s+([\w$.]+)\s*\((.*?)\)\s*(.*?)\s*\{",
    re.DOTALL,
)
_PARAM_SPLIT_RE = re.compile(r"\.param\s+")
_REQNTID_RE = re.compile(r"\.reqntid\s+(\d+)\s*,\s*(\d+)\s*,\s*(\d+)")
_ARRAY_RE = re.compile(r"\.b8\s+([\w$.]+)\s*\[\s*(\d+)\s*\]")
_SCALAR_RE = re.compile(r"\.(?:u|s|f|b)(8|16|32|64)\b\s+([\w$.]+)\s*$")
_ALIGN_RE = re.compile(r"\.align\s+(\d+)")

# `mov.b64 %rdN, <param>;` then `cvta.param.u64 %rdM, %rdN;` is how a by-value
# tensor map reaches the register a TMA instruction addresses it through.
_MOV_PARAM_RE = re.compile(r"mov\.b64\s+(%rd\d+)\s*,\s*([\w$.]+)\s*;")
_CVTA_PARAM_RE = re.compile(r"cvta\.param\.u64\s+(%rd\d+)\s*,\s*(%rd\d+)\s*;")
# A TMA store reads `[map, {coords}], [smem]` while a load reads
# `[smem], [map, {coords}]`, so the descriptor is the operand carrying the
# coordinate list rather than a fixed position.
_TMA_RE = re.compile(r"cp\.async\.bulk\.tensor\.(\d+)d\b")
_TMA_MAP_RE = re.compile(
    r"cp\.async\.bulk\.tensor\.(\d+)d\.(global|shared)[^\n;]*?\[\s*(%rd\d+)\s*,\s*\{"
)

# A CUtensorMap is an opaque 128-byte descriptor passed by value.
TENSOR_MAP_NBYTES = 128


@dataclass(frozen=True)
class PtxParam:
    """One declared kernel parameter."""

    name: str
    nbytes: int
    align: int
    is_pointer: bool
    tensor_rank: int | None = None
    tensor_direction: str | None = None

    @property
    def is_tensor_map(self) -> bool:
        """True for a by-value 128-byte blob, i.e. a CUtensorMap slot."""
        return not self.is_pointer and self.nbytes == TENSOR_MAP_NBYTES


@dataclass(frozen=True)
class PtxEntryMeta:
    kernel_name: str
    param_count: int
    reqntid: tuple[int, int, int] | None
    params: tuple[PtxParam, ...] = ()

    @property
    def block_size(self) -> int | None:
        if self.reqntid is None:
            return None
        x, y, z = self.reqntid
        return x * y * z

    @property
    def tensor_map_indices(self) -> tuple[int, ...]:
        return tuple(i for i, p in enumerate(self.params) if p.is_tensor_map)

    @property
    def uses_tensor_maps(self) -> bool:
        return bool(self.tensor_map_indices)


def resolve_block_size(meta: PtxEntryMeta, requested: int) -> int:
    """Prefer PTX .reqntid when present; otherwise use the CLI --block-size."""
    if meta.block_size is not None:
        return meta.block_size
    if requested <= 0:
        raise ValueError("--block-size must be positive")
    return requested


def validate_synthetic_launch_params(meta: PtxEntryMeta) -> None:
    """Reject parameters for which this example cannot reconstruct values."""
    unsupported = [
        f"{param.name} ({param.nbytes}-byte value)"
        for param in meta.params
        if not param.is_pointer and not param.is_tensor_map
    ]
    if unsupported:
        raise ValueError(
            "synthetic launch supports pointer and tensor-map parameters only; "
            "explicit values are unavailable for " + ", ".join(unsupported)
        )


def _parse_param(decl: str) -> PtxParam:
    text = decl.strip().rstrip(",").strip()
    align_match = _ALIGN_RE.search(text)
    align = int(align_match.group(1)) if align_match else 1

    array_match = _ARRAY_RE.search(text)
    if array_match:
        return PtxParam(
            name=array_match.group(1),
            nbytes=int(array_match.group(2)),
            align=align,
            is_pointer=False,
        )

    scalar_match = _SCALAR_RE.search(text)
    if scalar_match:
        bits = int(scalar_match.group(1))
        name = scalar_match.group(2)
    else:
        bits, name = 64, text.split()[-1]

    # `.ptr` is the explicit marker; a bare `.u64` in XLA output is also a
    # buffer address, and treating it as one is what makes the launch legal.
    is_pointer = ".ptr" in text or bits == 64
    return PtxParam(name=name, nbytes=bits // 8, align=align, is_pointer=is_pointer)


def _tensor_usage_by_param(body: str) -> dict[str, tuple[int, str]]:
    """Map descriptor param name -> (TMA rank, direction) via cvta.param chains."""
    reg_to_param: dict[str, str] = {}
    for match in _MOV_PARAM_RE.finditer(body):
        reg_to_param[match.group(1)] = match.group(2)

    cvta_to_param: dict[str, str] = {}
    for match in _CVTA_PARAM_RE.finditer(body):
        source = reg_to_param.get(match.group(2))
        if source is not None:
            cvta_to_param[match.group(1)] = source

    usage: dict[str, tuple[int, str]] = {}
    for match in _TMA_MAP_RE.finditer(body):
        param = cvta_to_param.get(match.group(3))
        if param is not None:
            direction = "store" if match.group(2) == "global" else "load"
            usage[param] = (int(match.group(1)), direction)
    return usage


def _entry_body(ptx_text: str, brace_index: int) -> str:
    depth = 0
    for i in range(brace_index, len(ptx_text)):
        char = ptx_text[i]
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return ptx_text[brace_index : i + 1]
    return ptx_text[brace_index:]


def inspect_ptx_entry(ptx_text: str, kernel_name: str) -> PtxEntryMeta:
    """Parse parameters, optional .reqntid, and TMA ranks for a PTX entry."""
    for match in _ENTRY_RE.finditer(ptx_text):
        name = match.group(1)
        if name != kernel_name:
            continue
        decls = [d for d in _PARAM_SPLIT_RE.split(match.group(2)) if d.strip()]
        params = [_parse_param(d) for d in decls]

        req = _REQNTID_RE.search(match.group(3))
        reqntid = None
        if req is not None:
            reqntid = (int(req.group(1)), int(req.group(2)), int(req.group(3)))

        body = _entry_body(ptx_text, match.end() - 1)
        usage = _tensor_usage_by_param(body)
        observed = {int(m.group(1)) for m in _TMA_RE.finditer(body)}
        sole_rank = observed.pop() if len(observed) == 1 else None
        params = [
            (
                param
                if not param.is_tensor_map
                else PtxParam(
                    name=param.name,
                    nbytes=param.nbytes,
                    align=param.align,
                    is_pointer=param.is_pointer,
                    tensor_rank=usage.get(param.name, (sole_rank, None))[0],
                    tensor_direction=usage.get(param.name, (None, None))[1],
                )
            )
            for param in params
        ]

        return PtxEntryMeta(
            kernel_name=name,
            param_count=len(params),
            reqntid=reqntid,
            params=tuple(params),
        )
    raise ValueError(f"PTX entry not found: {kernel_name!r}")

"""Decide which CUtensorMap layout backs each descriptor parameter.

A descriptor's layout is chosen on the host, so it is absent from PTX. Two
sources can supply it: an explicit layout file, or the XLA dump. The dump only
records the tile of a fusion's *output*, so a descriptor the kernel stores
through can be inferred while descriptors it loads operands through cannot.
Anything left unresolved is reported rather than guessed, because a wrong box
size makes a kernel move the wrong number of bytes into shared memory.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from xla_ciq.search.ptx_meta import PtxEntryMeta
from xla_ciq.xla.tensor_map import (
    TensorMapError,
    TensorMapSpec,
    find_fusion_layout,
    from_hlo_shape,
)


@dataclass(frozen=True)
class TensorMapPlan:
    specs: dict[int, TensorMapSpec]
    unresolved: tuple[int, ...] = ()
    notes: tuple[str, ...] = ()

    @property
    def is_complete(self) -> bool:
        return not self.unresolved

    @property
    def required(self) -> bool:
        return bool(self.specs) or bool(self.unresolved)

    def describe_gap(self, meta: PtxEntryMeta) -> str:
        names = [
            meta.params[i].name if i < len(meta.params) else f"param_{i}"
            for i in self.unresolved
        ]
        detail = "; ".join(self.notes)
        return (
            f"kernel {meta.kernel_name} needs tensor map layouts for "
            f"{', '.join(names)}; supply them with --tensor-maps"
            + (f" ({detail})" if detail else "")
        )


def resolve_tensor_maps(
    *,
    meta: PtxEntryMeta,
    ptx_path: Path | None = None,
    dump_dir: Path | None = None,
    overrides: dict[int, TensorMapSpec] | None = None,
) -> TensorMapPlan:
    """Build the descriptor layouts for a kernel, or say which are missing."""
    indices = meta.tensor_map_indices
    if not indices:
        return TensorMapPlan(specs={})

    overrides = overrides or {}
    specs: dict[int, TensorMapSpec] = {}
    unresolved: list[int] = []
    notes: list[str] = []

    layout = None
    if dump_dir is not None and dump_dir.is_dir():
        layout = find_fusion_layout(dump_dir, meta.kernel_name, ptx_path=ptx_path)
        if layout is None:
            notes.append("no fusion tile found in dump")

    for index in indices:
        if index in overrides:
            specs[index] = overrides[index]
            continue

        param = meta.params[index]
        if param.tensor_direction != "store":
            notes.append(f"{param.name} loads an operand, whose tile the dump omits")
            unresolved.append(index)
            continue
        if layout is None:
            unresolved.append(index)
            continue
        if param.tensor_rank is not None and param.tensor_rank != len(layout.tile):
            notes.append(
                f"{param.name} is rank {param.tensor_rank} but the fusion tile is "
                f"rank {len(layout.tile)}"
            )
            unresolved.append(index)
            continue
        try:
            specs[index] = from_hlo_shape(
                shape_token=layout.shape_token,
                tile=list(layout.tile),
                minor_to_major=list(layout.minor_to_major),
                source=layout.source,
            )
        except TensorMapError as exc:
            notes.append(f"{param.name}: {exc}")
            unresolved.append(index)

    return TensorMapPlan(
        specs=specs, unresolved=tuple(unresolved), notes=tuple(dict.fromkeys(notes))
    )

"""Sweep TMA descriptor tiles as CompileIQ search knobs.

The PTX for a TMA kernel is compiled against a fixed shared-memory layout, so
the host-side ``CUtensorMap`` box must match what the emitter assumed. When the
dump does not record that box (typical for load descriptors), CompileIQ can
search over legal box sizes and swizzle modes jointly with the PTXAS ACF space
via a multi-config search: ``[PtxasSearchSpace, tile_dict]``.
"""

from __future__ import annotations

import builtins
from typing import Any

from xla_ciq.xla.tensor_map import TensorMapError, TensorMapSpec

_POW2_BOXES = (1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192)
_SWIZZLES = (0, 32, 64, 128)
_TMA_ALIGN_BYTES = 16
# Nested search-space root; restored into the objective as config["tm"].
TILE_SPACE_ROOT = "tm"
# Joint ACF×tile search explodes quickly; keep only the seed box and one
# octave above/below so early generations still sample the probed layout.
_NEAR_SEED_FACTORS = (1, 2)


def legal_box_sizes(
    dim: int,
    *,
    element_size: int,
    innermost: bool,
    seed: int | None = None,
) -> list[int]:
    """Positive box sizes that fit `dim` and satisfy TMA alignment when innermost.

    When a seed box is known (dump or ``--tensor-maps``), only that value and
    one octave nearby are offered. Otherwise every legal power-of-two up to
    ``dim`` is allowed so a cold search can still discover a working tile.
    """
    if dim <= 0:
        return []

    def _ok(size: int) -> bool:
        if size <= 0 or size > dim:
            return False
        if innermost and (size * element_size) % _TMA_ALIGN_BYTES:
            return False
        return True

    sizes: list[int] = []
    if seed is not None and _ok(seed):
        sizes.append(seed)
        for factor in _NEAR_SEED_FACTORS[1:]:
            for candidate in (seed * factor, max(1, seed // factor)):
                if _ok(candidate) and candidate not in sizes:
                    sizes.append(candidate)
        return sizes

    for size in _POW2_BOXES:
        if size > dim:
            break
        if _ok(size):
            sizes.append(size)
    if _ok(dim) and dim not in sizes:
        sizes.append(dim)
    return sizes


def box_size_options(spec: TensorMapSpec, axis: int) -> list[int]:
    """Box sizes offered for one axis, seed first.

    Derived only from the seed spec so the search space and the objective that
    decodes a sample always agree on the option list.
    """
    return legal_box_sizes(
        spec.dims[axis],
        element_size=spec.element_size,
        innermost=(axis == 0),
        seed=spec.box[axis],
    )


def swizzle_options(spec: TensorMapSpec) -> list[int]:
    """Swizzle modes offered for a descriptor, seed first."""
    seed = spec.swizzle_bytes if spec.swizzle_bytes is not None else 0
    options = [seed]
    for value in spec.swizzle_candidates():
        if value not in options:
            options.append(value)
    for value in _SWIZZLES:
        if value not in options and (
            value == 0 or value <= spec.box[0] * spec.element_size
        ):
            options.append(value)
    return options[:4]


def _index_knob(count: int) -> Any:
    """Knob selecting an option index, with init pinned to the seed (index 0).

    ``choice`` samples uniformly and cannot be seeded, so a wide joint space
    would almost never reproduce the seed layout that is known to launch. A
    ``range`` with ``seed_low``/``seed_high`` on the seed index makes CompileIQ
    initialize ``init_with_true_random_threshold`` of the first generation on it.
    """
    from compileiq.search_spaces.base import literal
    from compileiq.search_spaces.base import range as ciq_range

    if count <= 1:
        return literal(0)
    return ciq_range(0, count - 1, 1, seed_low=0, seed_high=0)


def build_tile_search_space(
    specs: dict[int, TensorMapSpec],
    *,
    sweep_indices: tuple[int, ...] | None = None,
) -> dict[str, Any]:
    """CompileIQ dict search space over box dims + swizzle for each descriptor.

    Knob values are indices into the per-axis option lists, not sizes, so that
    the seed layout is index 0 everywhere and can be pinned at search init.
    Requires ``compileiq.search_spaces.base`` at call time so unit tests can
    exercise the pure helpers without importing CompileIQ.
    """
    indices = sweep_indices if sweep_indices is not None else tuple(sorted(specs))
    if not indices:
        raise TensorMapError("no tensor map parameters to sweep")

    per_param: dict[str, dict[str, Any]] = {}
    for index in indices:
        if index not in specs:
            raise TensorMapError(f"cannot sweep missing tensor map param {index}")
        spec = specs[index]
        spec.validate()
        entry: dict[str, Any] = {}
        for axis in builtins.range(spec.rank):
            sizes = box_size_options(spec, axis)
            if not sizes:
                raise TensorMapError(
                    f"no legal box sizes for tensor map[{index}] axis {axis} "
                    f"dim={spec.dims[axis]}"
                )
            entry[f"b{axis}"] = _index_knob(len(sizes))
        entry["swz"] = _index_knob(len(swizzle_options(spec)))
        per_param[str(index)] = entry
    return {TILE_SPACE_ROOT: per_param}


def default_sweep_indices(specs: dict[int, TensorMapSpec]) -> tuple[int, ...]:
    """Prefer sweeping guessed/file layouts; fall back to every descriptor.

    Dump-inferred *store* tiles are usually authoritative. Load layouts from
    ``--tensor-maps`` are the ones we do not trust, so they are swept first.
    """
    guessed = [
        index
        for index, spec in sorted(specs.items())
        if spec.source.startswith("file:")
        or spec.source.startswith("guess:")
        or spec.source == "explicit"
    ]
    if guessed:
        return tuple(guessed)
    return tuple(sorted(specs))


def _option_index(value: Any, count: int) -> int:
    """Clamp a sampled knob value to a valid option index."""
    try:
        index = int(value)
    except (TypeError, ValueError) as exc:
        raise TensorMapError(f"tile option index must be an int, got {value!r}") from exc
    return max(0, min(index, count - 1))


def apply_tile_config(
    base: dict[int, TensorMapSpec],
    tiles: dict[str, Any] | None,
) -> dict[int, TensorMapSpec]:
    """Overlay a CompileIQ tile sample onto the seed tensor-map specs."""
    if not tiles:
        return dict(base)
    root = tiles.get(TILE_SPACE_ROOT, tiles)
    if not isinstance(root, dict):
        raise TensorMapError(f"tile config must be a dict, got {type(root).__name__}")

    updated = dict(base)
    for key, payload in root.items():
        try:
            index = int(key)
        except (TypeError, ValueError) as exc:
            raise TensorMapError(f"tile config key must be a param index, got {key!r}") from exc
        if index not in base:
            raise TensorMapError(f"tile config references unknown param {index}")
        if not isinstance(payload, dict):
            raise TensorMapError(f"tile config for param {index} must be an object")
        seed = base[index]
        box = list(seed.box)
        for axis in range(seed.rank):
            field = f"b{axis}"
            if field in payload and payload[field] is not None:
                sizes = box_size_options(seed, axis)
                box[axis] = sizes[_option_index(payload[field], len(sizes))]
        swizzle = seed.swizzle_bytes
        if "swz" in payload and payload["swz"] is not None:
            options = swizzle_options(seed)
            swizzle = options[_option_index(payload["swz"], len(options))]
        spec = TensorMapSpec(
            dtype=seed.dtype,
            dims=seed.dims,
            box=tuple(box),
            element_strides=seed.element_strides,
            swizzle_bytes=swizzle,
            source=f"sweep:{seed.source}" if seed.source else "sweep",
        )
        spec.validate()
        updated[index] = spec
    return updated


def unpack_search_config(config: Any) -> tuple[Any, dict[str, Any]]:
    """Split a multi-config sample into ``(acf_payload, tile_dict)``.

    Single-config PTXAS searches still pass a bare ACF hex string. Multi-config
    searches pass ``[acf, tiles]`` in the order the search spaces were listed.
    """
    if isinstance(config, list):
        if not config:
            raise TensorMapError("empty multi-config search sample")
        acf = config[0]
        tiles = config[1] if len(config) > 1 else {}
        if tiles is None:
            tiles = {}
        if not isinstance(tiles, dict):
            raise TensorMapError(
                f"tile config must be a dict, got {type(tiles).__name__}"
            )
        return acf, tiles
    return config, {}


def describe_tile_config(
    base: dict[int, TensorMapSpec],
    tiles: dict[str, Any] | None,
) -> str:
    """One-line summary of a tile sample for search notes.

    Knob values are option indices, so resolve them against the seed specs to
    report the box and swizzle the descriptor was actually built with.
    """
    if not tiles:
        return ""
    try:
        resolved = apply_tile_config(base, tiles)
    except TensorMapError as exc:
        return f"<unresolvable tile config: {exc}>"
    root = tiles.get(TILE_SPACE_ROOT, tiles)
    swept = sorted(root) if isinstance(root, dict) else sorted(resolved)
    parts: list[str] = []
    for key in swept:
        try:
            index = int(key)
        except (TypeError, ValueError):
            continue
        spec = resolved.get(index)
        if spec is None:
            continue
        box = ",".join(str(value) for value in spec.box)
        parts.append(f"param[{index}] box=[{box}] swizzle={spec.swizzle_bytes}")
    return "; ".join(parts)

"""Smoke-test an encrypted search-space artifact through the public CompileIQ API."""

from __future__ import annotations

import argparse
import hashlib
import json
from collections.abc import Sequence
from pathlib import Path
from typing import Any

from compileiq.ciq import Search
from compileiq.types import SearchConfiguration


def _positive_int(value: str) -> int:
    parsed = int(value)
    if parsed < 1:
        raise argparse.ArgumentTypeError("must be at least 1")
    return parsed


def _sha256_value(value: str) -> str:
    normalized = value.removeprefix("sha256:").lower()
    if len(normalized) != 64:
        raise argparse.ArgumentTypeError("must be a 64-character SHA-256 digest")
    try:
        bytes.fromhex(normalized)
    except ValueError as error:
        raise argparse.ArgumentTypeError("must be a hexadecimal SHA-256 digest") from error
    return normalized


def _decode_candidate(candidate: object, index: int) -> bytes:
    if not isinstance(candidate, str) or not candidate:
        raise RuntimeError(f"candidate {index} is not a non-empty encrypted hex string")

    try:
        decoded = bytes.fromhex(candidate)
    except ValueError as error:
        raise RuntimeError(f"candidate {index} is not valid hexadecimal") from error

    if not decoded:
        raise RuntimeError(f"candidate {index} decodes to an empty payload")
    return decoded


def _smoke_objective(candidate: object) -> float:
    """Return a deterministic score while validating the protected candidate boundary."""
    return float(len(_decode_candidate(candidate, 0)))


def _sha256(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()


def _write_candidates(candidates: Sequence[object], output_dir: Path) -> list[dict[str, Any]]:
    output_dir.mkdir(parents=True)
    manifest: list[dict[str, Any]] = []
    for index, candidate in enumerate(candidates):
        payload = _decode_candidate(candidate, index)
        filename = f"candidate-{index:03d}.bin"
        (output_dir / filename).write_bytes(payload)
        manifest.append(
            {
                "filename": filename,
                "sha256": _sha256(payload),
                "size_bytes": len(payload),
            }
        )
    return manifest


def _new_search(search_space: Path, cache_dir: Path, pool_size: int, cull_size: int) -> Search:
    return Search(
        objective_function=_smoke_objective,
        search_space=search_space,
        search_config=SearchConfiguration(
            generations=1,
            pool_size=pool_size,
            cull_size=cull_size,
            problem_type="min",
            num_objectives=1,
        ),
        cache_folder=cache_dir,
        disable_progress_bar=True,
    )


def _run_sample(
    search_space: Path,
    output_dir: Path,
    sample_count: int,
    pool_size: int,
    cull_size: int,
) -> dict[str, Any]:
    search = _new_search(search_space, output_dir / "cache", pool_size, cull_size)
    candidates = search.sample(num_samples=sample_count)
    if len(candidates) != sample_count:
        raise RuntimeError(
            f"sample() returned {len(candidates)} candidates; expected {sample_count}"
        )
    return {
        "candidate_count": len(candidates),
        "candidates": _write_candidates(candidates, output_dir / "candidates"),
    }


def _run_search(
    search_space: Path,
    output_dir: Path,
    pool_size: int,
    cull_size: int,
    workers: int,
) -> dict[str, Any]:
    search = _new_search(search_space, output_dir / "cache", pool_size, cull_size)
    results = search.start(num_workers=workers).get_results()
    required_columns = {"score_1", "params", "generation"}
    missing_columns = sorted(required_columns.difference(results.columns))
    if missing_columns:
        raise RuntimeError(f"search results are missing columns: {', '.join(missing_columns)}")
    if results.empty:
        raise RuntimeError("search returned no results")
    if len(results) > pool_size:
        raise RuntimeError(
            f"search returned {len(results)} rows; expected no more than {pool_size}"
        )

    candidates = results["params"].tolist()
    return {
        "candidate_count": len(candidates),
        "candidates": _write_candidates(candidates, output_dir / "candidates"),
        "result_columns": sorted(results.columns.tolist()),
        "result_rows": len(results),
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--search-space", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument("--mode", choices=("sample", "search", "both"), default="both")
    parser.add_argument("--samples", type=_positive_int, default=8)
    parser.add_argument("--pool-size", type=_positive_int, default=6)
    parser.add_argument("--cull-size", type=_positive_int, default=2)
    parser.add_argument("--workers", type=_positive_int, default=1)
    parser.add_argument("--expected-sha256", type=_sha256_value)
    parser.add_argument("--expected-size", type=_positive_int)
    args = parser.parse_args()

    if not args.search_space.is_file():
        parser.error(f"search-space file does not exist: {args.search_space}")
    if args.cull_size >= args.pool_size:
        parser.error("--cull-size must be smaller than --pool-size")
    artifact = args.search_space.read_bytes()
    artifact_sha256 = _sha256(artifact)
    if args.expected_sha256 is not None and artifact_sha256 != args.expected_sha256:
        parser.error(
            f"search-space SHA-256 mismatch: expected {args.expected_sha256}, "
            f"got {artifact_sha256}"
        )
    if args.expected_size is not None and len(artifact) != args.expected_size:
        parser.error(
            f"search-space size mismatch: expected {args.expected_size}, got {len(artifact)}"
        )
    if args.output_dir.exists() and any(args.output_dir.iterdir()):
        parser.error(f"output directory must be empty: {args.output_dir}")
    args.output_dir.mkdir(parents=True, exist_ok=True)

    manifest: dict[str, Any] = {
        "artifact": {
            "filename": args.search_space.name,
            "sha256": artifact_sha256,
            "size_bytes": len(artifact),
        },
        "mode": args.mode,
        "schema_version": 1,
    }
    if args.mode in {"sample", "both"}:
        manifest["sample"] = _run_sample(
            args.search_space,
            args.output_dir / "sample",
            args.samples,
            max(args.pool_size, args.samples),
            args.cull_size,
        )
    if args.mode in {"search", "both"}:
        manifest["search"] = _run_search(
            args.search_space,
            args.output_dir / "search",
            args.pool_size,
            args.cull_size,
            args.workers,
        )

    manifest_path = args.output_dir / "manifest.json"
    manifest_path.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n")
    print(json.dumps(manifest, sort_keys=True))


if __name__ == "__main__":
    main()
